import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`vs-copilot`,heroTitle:`A Team, Not a Copilot`,heroSubtitle:`One AI assistant can only do so much. Computer deploys 19 models as a coordinated team — each one handling what it's best at, working for hours on your project.`,inputUrlCta:`Compare my workflow`,inputUrlPlaceholder:`Describe your workflow`,inputUrlPrefill:`Go to {url} and perform a deep comparison of this workflow or task against what Microsoft Copilot can do versus Perplexity Computer. 1) Analyze the site or description to identify the user's core workflow — what they're trying to accomplish, the tools involved, and the expected deliverables. 2) Attempt to replicate this workflow using Microsoft Copilot's known capabilities — single-model chat, Microsoft 365 integrations, and inline suggestions. Document where Copilot falls short: single-model limitation, no autonomous multi-step execution, no sub-agent orchestration, no sandboxed cloud environment. 3) Design how Perplexity Computer would handle the same workflow: break it into sub-tasks, assign specialized AI models to each, spin up sub-agents, connect to required tools, and run autonomously for as long as needed. 4) Produce a side-by-side comparison table with rows for: number of models used, autonomous execution time, sub-agent support, tool integrations, sandboxed environment, persistent memory, and output format. 5) Deliver a full workflow blueprint showing exactly how Computer would execute the task end-to-end — with numbered steps, model assignments, and expected deliverables.`,heroOverlaySteps:[`Analyzing your workflow requirements and complexity`,`Spinning up specialized sub-agents for each task`,`Orchestrating models across a sandboxed cloud environment`,`Completed deliverables with full audit trail — ready to review`],generatingSteps:[`Evaluating your task to determine the optimal model and agent configuration`,`Designing an agent to break your project into subtasks and assign specialized models`,`Configuring sandboxed cloud execution with persistent memory and tool integrations`,`Setting up multi-step orchestration with deliverable packaging and monitoring`],featureSectionTitle:`From prompt to finished project`,featureCardTitles:[`Connects to your entire stack`,`Outputs you can ship`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Sheets, Google Drive, Slack, Notion, GitHub, Airtable, Trello — Computer plugs into your tools so workflows run across every system you use.`,`Research reports. Data analyses. Multi-file codebases. Strategy documents. Spreadsheets with formulas. Computer delivers finished work — not chat suggestions.`],capabilitySectionTitle:`Your digital worker, on autopilot`,capabilitySectionSubtitle:`Describe the project, step away, come back to finished deliverables.`,capabilityCards:[{title:`Multi-Model Orchestration`,description:`Computer can route each subtask to the best model — coding to one, analysis to another, writing to a third — and merge results into a single deliverable.`},{title:`Autonomous Sub-Agents`,description:`Computer can spawn specialized agents that work in parallel — researching, building, and validating simultaneously instead of one prompt at a time.`},{title:`Multi-Hour Execution`,description:`Computer can run complex workflows for hours in a sandboxed cloud — no session timeouts, no lost context, no babysitting required.`},{title:`Connect Your Tools`,description:`Computer can read and write across Gmail, Google Sheets, Slack, Notion, GitHub, and more — build workflows that span your entire tool stack.`},{title:`Persistent Memory`,description:`Computer can remember your preferences, past projects, and organizational context across sessions — so every workflow builds on what it already knows.`},{title:`Monitor & Alert`,description:`Computer can track running workflows and alert you when deliverables are ready, errors need attention, or scheduled tasks complete.`}]});export{t as default};
